export const envelope = [13, 27, 13];

export default function build(api) {
  const [W, H, D] = api.size;
  const seatY = 5;
  const instIdx = api.instance.index;

  // Grid buffer to ensure deterministic single-write placement and prevent clipping
  const grid = new Array(W * H * D).fill(null);

  function idx(x, y, z) {
    return x + z * W + y * (W * D);
  }

  function setVoxel(x, y, z, block) {
    if (x >= 0 && x < W && y >= 0 && y < H && z >= 0 && z < D) {
      grid[idx(x, y, z)] = block;
    }
  }

  function getVoxel(x, y, z) {
    if (x >= 0 && x < W && y >= 0 && y < H && z >= 0 && z < D) {
      return grid[idx(x, y, z)];
    }
    return null;
  }

  // --- Vector Math Utilities ---
  function dot(a, b) {
    return a[0] * b[0] + a[1] * b[1] + a[2] * b[2];
  }

  function cross(a, b) {
    return [
      a[1] * b[2] - a[2] * b[1],
      a[2] * b[0] - a[0] * b[2],
      a[0] * b[1] - a[1] * b[0]
    ];
  }

  function len(a) {
    return Math.hypot(a[0], a[1], a[2]);
  }

  function norm(a) {
    const l = len(a);
    if (l < 1e-6) return [0, 1, 0];
    return [a[0] / l, a[1] / l, a[2] / l];
  }

  // 4th-degree Bezier Spline
  function evalBezier(t, p0, p1, p2, p3, p4) {
    const u = 1 - t;
    const tt = t * t;
    const uu = u * u;
    const uuu = uu * u;
    const ttt = tt * t;

    const c0 = uuu * u;
    const c1 = 4 * uuu * t;
    const c2 = 6 * uu * tt;
    const c3 = 4 * u * ttt;
    const c4 = tt * tt;

    return [
      c0 * p0[0] + c1 * p1[0] + c2 * p2[0] + c3 * p3[0] + c4 * p4[0],
      c0 * p0[1] + c1 * p1[1] + c2 * p2[1] + c3 * p3[1] + c4 * p4[1],
      c0 * p0[2] + c1 * p1[2] + c2 * p2[2] + c3 * p3[2] + c4 * p4[2]
    ];
  }

  function evalBezierDeriv(t, p0, p1, p2, p3, p4) {
    const u = 1 - t;
    const tt = t * t;
    const uu = u * u;

    const c0 = 4 * uu * u;
    const c1 = 12 * uu * t;
    const c2 = 12 * u * tt;
    const c3 = 4 * tt * t;

    const d0 = [p1[0] - p0[0], p1[1] - p0[1], p1[2] - p0[2]];
    const d1 = [p2[0] - p1[0], p2[1] - p1[1], p2[2] - p1[2]];
    const d2 = [p3[0] - p2[0], p3[1] - p2[1], p3[2] - p2[2]];
    const d3 = [p4[0] - p3[0], p4[1] - p3[1], p4[2] - p3[2]];

    return [
      c0 * d0[0] + c1 * d1[0] + c2 * d2[0] + c3 * d3[0],
      c0 * d0[1] + c1 * d1[1] + c2 * d2[1] + c3 * d3[1],
      c0 * d0[2] + c1 * d1[2] + c2 * d2[2] + c3 * d3[2]
    ];
  }

  function evalBezierCurv(t, p0, p1, p2, p3, p4) {
    const u = 1 - t;
    const c0 = 12 * u * u;
    const c1 = 24 * u * t;
    const c2 = 12 * t * t;

    const dd0 = [p2[0] - 2 * p1[0] + p0[0], p2[1] - 2 * p1[1] + p0[1], p2[2] - 2 * p1[2] + p0[2]];
    const dd1 = [p3[0] - 2 * p2[0] + p1[0], p3[1] - 2 * p2[1] + p1[1], p3[2] - 2 * p2[2] + p1[2]];
    const dd2 = [p4[0] - 2 * p3[0] + p2[0], p4[1] - 2 * p3[1] + p2[1], p4[2] - 2 * p3[2] + p2[2]];

    return [
      c0 * dd0[0] + c1 * dd1[0] + c2 * dd2[0],
      c0 * dd0[1] + c1 * dd1[1] + c2 * dd2[1],
      c0 * dd0[2] + c1 * dd1[2] + c2 * dd2[2]
    ];
  }

  // --- Procedural Generation & Instance Variations ---
  const cx = 6.0;
  const cz = 6.0;

  // PRNG Jitter per instance
  const jx0 = (api.random() - 0.5) * 1.4;
  const jz0 = (api.random() - 0.5) * 1.2;
  const jx1 = (api.random() - 0.5) * 2.0;
  const jy1 = (api.random() - 0.5) * 2.0;
  const jz1 = (api.random() - 0.5) * 1.5;

  const archType = instIdx % 5;
  let p0, p1, p2, p3, p4;

  if (archType === 0) {
    // Aggressive Forward Lunge
    p0 = [cx + jx0, seatY - 1, cz + 2.8 + jz0];
    p1 = [cx + jx1 * 0.4, seatY + 8 + jy1 * 0.5, cz + 2.0 + jz1 * 0.5];
    p2 = [cx + jx1 * 0.2, seatY + 16, cz - 0.6];
    p3 = [cx - jx1 * 0.3, seatY + 19, cz - 3.4];
    p4 = [cx - jx1 * 0.5, seatY + 13, cz - 4.6];
  } else if (archType === 1) {
    // Sky Coiler (Ascending Spiral Loop)
    p0 = [cx + 1.2 + jx0, seatY - 1, cz + 2.2 + jz0];
    p1 = [cx - 2.2, seatY + 8 + jy1 * 0.5, cz + 1.2];
    p2 = [cx - 1.6, seatY + 18, cz - 1.8];
    p3 = [cx + 2.4, seatY + 21, cz - 1.2];
    p4 = [cx + 0.6, seatY + 15, cz - 3.6];
  } else if (archType === 2) {
    // Serpentine S-Thrash
    p0 = [cx - 0.8 + jx0, seatY - 1, cz + 2.6 + jz0];
    p1 = [cx + 2.8, seatY + 7 + jy1 * 0.5, cz + 1.5];
    p2 = [cx - 2.4, seatY + 14, cz - 0.4];
    p3 = [cx + 1.2, seatY + 19, cz - 2.4];
    p4 = [cx - 1.2, seatY + 16, cz - 4.4];
  } else if (archType === 3) {
    // Breaching Leviathan (High Arch Smash)
    p0 = [cx + 0.5 + jx0, seatY - 1, cz + 2.0 + jz0];
    p1 = [cx + 0.8, seatY + 11 + jy1 * 0.5, cz + 1.6];
    p2 = [cx - 0.4, seatY + 22, cz + 0.2];
    p3 = [cx - 0.6, seatY + 21, cz - 2.8];
    p4 = [cx - 0.2, seatY + 10, cz - 4.4];
  } else {
    // Grasping Tendril Hook
    p0 = [cx + jx0, seatY - 1, cz + 3.0 + jz0];
    p1 = [cx + 1.8, seatY + 9 + jy1 * 0.5, cz + 0.8];
    p2 = [cx - 1.8, seatY + 16, cz - 1.4];
    p3 = [cx - 2.0, seatY + 18, cz - 3.6];
    p4 = [cx + 0.6, seatY + 13, cz - 2.8];
  }

  // Radius parameters
  const rBase = 2.8 + api.random() * 0.5;
  const rTip = 0.55 + api.random() * 0.15;

  function calcRadius(t) {
    return rBase * Math.pow(1 - t, 0.75) * (1 - 0.25 * t) + rTip * t;
  }

  // Sample Spline
  const SAMPLES = 120;
  const pts = [];
  const tans = [];
  const curvs = [];
  const radii = [];
  const arcLens = [];

  let cumLen = 0;
  let lastP = evalBezier(0, p0, p1, p2, p3, p4);

  for (let i = 0; i <= SAMPLES; i++) {
    const t = i / SAMPLES;
    const p = evalBezier(t, p0, p1, p2, p3, p4);
    const d = evalBezierDeriv(t, p0, p1, p2, p3, p4);
    const c = evalBezierCurv(t, p0, p1, p2, p3, p4);

    if (i > 0) {
      cumLen += len([p[0] - lastP[0], p[1] - lastP[1], p[2] - lastP[2]]);
    }

    pts.push(p);
    tans.push(norm(d));
    curvs.push(c);
    radii.push(calcRadius(t));
    arcLens.push(cumLen);

    lastP = p;
  }

  // Palette variant per instance
  const palVariant = instIdx % 4;
  let skinPrimary = "minecraft:prismarine";
  let skinSecondary = "minecraft:dark_prismarine";
  let skinAccent = "minecraft:cyan_terracotta";
  let suckerRim = "minecraft:smooth_sandstone";
  let suckerCore = "minecraft:sea_lantern";
  let dorsalSpine = "minecraft:dark_prismarine_stairs[facing=north,half=bottom]";

  if (palVariant === 1) {
    skinPrimary = "minecraft:prismarine_bricks";
    skinSecondary = "minecraft:warped_hyphae";
    skinAccent = "minecraft:warped_wart_block";
    suckerRim = "minecraft:pearlescent_froglight";
    suckerCore = "minecraft:shroomlight";
    dorsalSpine = "minecraft:crying_obsidian";
  } else if (palVariant === 2) {
    skinPrimary = "minecraft:dark_prismarine";
    skinSecondary = "minecraft:cyan_terracotta";
    skinAccent = "minecraft:crying_obsidian";
    suckerRim = "minecraft:bone_block";
    suckerCore = "minecraft:ochre_froglight";
    dorsalSpine = "minecraft:prismarine_wall";
  } else if (palVariant === 3) {
    skinPrimary = "minecraft:prismarine";
    skinSecondary = "minecraft:dark_prismarine";
    skinAccent = "minecraft:calcite";
    suckerRim = "minecraft:smooth_quartz";
    suckerCore = "minecraft:sea_lantern";
    dorsalSpine = "minecraft:end_rod[facing=up]";
  }

  // --- Volumetric Tentacle Rasterization ---
  for (let x = 0; x < W; x++) {
    for (let y = 0; y < H; y++) {
      for (let z = 0; z < D; z++) {
        const px = x + 0.5;
        const py = y + 0.5;
        const pz = z + 0.5;

        // Find closest point on spline
        let bestDistSq = 1e9;
        let bestI = 0;
        for (let i = 0; i <= SAMPLES; i++) {
          const sp = pts[i];
          const dx = px - sp[0];
          const dy = py - sp[1];
          const dz = pz - sp[2];
          const d2 = dx * dx + dy * dy + dz * dz;
          if (d2 < bestDistSq) {
            bestDistSq = d2;
            bestI = i;
          }
        }

        const sp = pts[bestI];
        const T = tans[bestI];
        const R = radii[bestI];
        const sArc = arcLens[bestI];

        const Vraw = [px - sp[0], py - sp[1], pz - sp[2]];
        const vPar = dot(Vraw, T);
        const Vperp = [Vraw[0] - vPar * T[0], Vraw[1] - vPar * T[1], Vraw[2] - vPar * T[2]];

        // Establish Frenet / Curvature reference frame
        const K = curvs[bestI];
        const kPar = dot(K, T);
        let Kperp = [K[0] - kPar * T[0], K[1] - kPar * T[1], K[2] - kPar * T[2]];

        let U;
        if (len(Kperp) > 0.05) {
          U = norm(Kperp); // points to inside of curve (sucker side)
        } else {
          // Fallback ventral reference vector pointing forward/down
          const defV = [0, -0.6, -0.8];
          const defPar = dot(defV, T);
          U = norm([defV[0] - defPar * T[0], defV[1] - defPar * T[1], defV[2] - defPar * T[2]]);
        }

        const Wside = cross(T, U);

        const u = dot(Vperp, U);
        const w = dot(Vperp, Wside);

        // Cross-sectional oval/teardrop profile
        let rEff = R;
        if (u >= 0) {
          rEff = R * (1.0 - 0.06 * (u / R));
        } else {
          rEff = R * (1.0 + 0.12 * (u / R));
        }

        const rNorm = Math.hypot(u, w) / rEff;

        if (rNorm <= 1.05) {
          // Inside tentacle body
          let chosenBlock = skinPrimary;

          // Suction Cups Zone (ventral side)
          if (u > 0.25 * R && rNorm >= 0.5) {
            const cupSpacing = 1.9;
            const wOff = 0.45 * R;

            const sRel1 = (sArc % cupSpacing) - cupSpacing * 0.5;
            const wRel1 = w - wOff;
            const dSuck1 = Math.hypot(sRel1, wRel1);

            const sRel2 = ((sArc + cupSpacing * 0.5) % cupSpacing) - cupSpacing * 0.5;
            const wRel2 = w + wOff;
            const dSuck2 = Math.hypot(sRel2, wRel2);

            const dSuck = Math.min(dSuck1, dSuck2);

            if (dSuck < 0.65) {
              if (rNorm > 0.82) {
                chosenBlock = suckerRim;
              } else {
                chosenBlock = suckerCore;
              }
            } else if (u > 0.45 * R) {
              chosenBlock = "minecraft:prismarine_bricks";
            }
          } else if (u < -0.35 * R) {
            // Dorsal scale / spine ridge
            if (Math.abs(w) < 0.45) {
              if ((sArc % 3.2) < 0.8 && rNorm > 0.72) {
                chosenBlock = (palVariant % 2 === 0) ? "minecraft:sea_lantern" : "minecraft:crying_obsidian";
              } else {
                chosenBlock = skinSecondary;
              }
            } else {
              chosenBlock = skinSecondary;
            }
          } else {
            // Lateral skin with natural mottled texture
            const noise = Math.sin(x * 12.3 + y * 7.1 + z * 5.9);
            if (noise > 0.55) {
              chosenBlock = skinAccent;
            } else if (noise < -0.45) {
              chosenBlock = skinSecondary;
            } else {
              chosenBlock = skinPrimary;
            }
          }

          // Deep muscle core
          if (rNorm < 0.45) {
            chosenBlock = "minecraft:dark_prismarine";
          }

          setVoxel(x, y, z, chosenBlock);
        } else if (rNorm <= 1.45 && u < -0.7 * R && Math.abs(w) < 0.45) {
          // Dorsal spikes outside main skin
          if ((sArc % 2.6) < 0.85) {
            setVoxel(x, y, z, dorsalSpine);
          }
        }
      }
    }
  }

  // --- Narrative / Hellenic City Invasion Debris ---
  const debrisType = instIdx % 4;

  if (debrisType === 0) {
    // Clenched Fluted Marble Column fragment from Hellenic Stoa
    const midIdx = Math.floor(SAMPLES * 0.62);
    const colCenter = pts[midIdx];
    const uDir = tans[midIdx];

    const cxCol = Math.round(colCenter[0] + uDir[0] * 1.5);
    const cyCol = Math.round(colCenter[1]);
    const czCol = Math.round(colCenter[2] - 1.2);

    for (let dy = -1; dy <= 2; dy++) {
      const yL = cyCol + dy;
      if (yL >= 0 && yL < H) {
        setVoxel(cxCol, yL, czCol, "minecraft:quartz_pillar[axis=y]");
        if (dy === 2) {
          setVoxel(cxCol, yL, czCol, "minecraft:smooth_quartz_stairs[facing=south,half=top]");
        }
      }
    }
  } else if (debrisType === 1) {
    // Shattered Promenade Pier Timbers at base
    const logBlock = api.theme.wood.log || "minecraft:oak_log[axis=y]";
    const fenceBlock = api.theme.wood.fence || "minecraft:oak_fence";
    const px = Math.round(p0[0] + 1.8);
    const pz = Math.round(p0[2] + 1.2);

    for (let dy = 0; dy <= 3; dy++) {
      const yL = seatY + dy;
      if (dy <= 2) {
        setVoxel(px, yL, pz, logBlock);
      } else {
        setVoxel(px, yL, pz, fenceBlock);
      }
    }
  } else if (debrisType === 2) {
    // Ballista Harpoon Bolt fired by city defenders embedded in hide
    const harpoonIdx = Math.floor(SAMPLES * 0.42);
    const hpPos = pts[harpoonIdx];
    const hx = Math.round(hpPos[0] + 1.8);
    const hy = Math.round(hpPos[1]);
    const hz = Math.round(hpPos[2] + 1.0);

    setVoxel(hx, hy, hz, "minecraft:iron_bars");
    setVoxel(hx + 1, hy, hz, "minecraft:chain[axis=x]");
    setVoxel(hx - 1, hy, hz, "minecraft:end_rod[facing=west]");
  } else {
    // Deep Abyssal Coral & Barnacles
    const cIdx = Math.floor(SAMPLES * 0.35);
    const cp = pts[cIdx];
    const bx = Math.round(cp[0] - 1.8);
    const by = Math.round(cp[1]);
    const bz = Math.round(cp[2]);

    setVoxel(bx, by, bz, "minecraft:bubble_coral_block");
    setVoxel(bx, by + 1, bz, "minecraft:calcite");
    setVoxel(bx, by - 1, bz, "minecraft:horn_coral_block");
  }

  // --- Water Splash Collar & Sea Foam Eruption ---
  const rootX = p0[0];
  const rootZ = p0[2];
  const splashMinR = rBase * 0.9;
  const splashMaxR = rBase + 2.2;

  for (let x = 0; x < W; x++) {
    for (let z = 0; z < D; z++) {
      const dRoot = Math.hypot(x + 0.5 - rootX, z + 0.5 - rootZ);
      if (dRoot >= splashMinR && dRoot <= splashMaxR) {
        const hGround = api.heightAt(x, z);
        const yBase = Math.max(0, Math.min(H - 1, seatY + hGround));

        // Plume height varies radially and with noise
        const angle = Math.atan2(z + 0.5 - rootZ, x + 0.5 - rootX);
        const noise = Math.sin(x * 7.7 + z * 13.1);
        const plumeH = Math.floor(1 + (noise * 0.5 + 0.5) * 2.5 + Math.max(0, -Math.cos(angle)) * 1.5);

        for (let dy = 0; dy <= plumeH; dy++) {
          const yL = yBase + dy;
          if (yL < H && !getVoxel(x, yL, z)) {
            let splashBlock = "minecraft:calcite";
            if (dy === plumeH) {
              splashBlock = (noise > 0) ? "minecraft:quartz_slab[type=bottom]" : "minecraft:calcite";
            } else if (dy === plumeH - 1 && noise > 0.4) {
              splashBlock = "minecraft:sea_lantern";
            } else if (noise < -0.3) {
              splashBlock = "minecraft:diorite";
            }
            setVoxel(x, yL, z, splashBlock);
          }
        }
      }
    }
  }

  // --- Terrain Conformance & Skirt Foundation ---
  // Every occupied column reads heightAt(x, z) and extends solidly downward
  for (let x = 0; x < W; x++) {
    for (let z = 0; z < D; z++) {
      let lowestOccupiedY = -1;
      for (let y = 0; y < H; y++) {
        if (getVoxel(x, y, z) !== null) {
          lowestOccupiedY = y;
          break;
        }
      }

      if (lowestOccupiedY !== -1 && lowestOccupiedY <= seatY + 4) {
        const hGround = api.heightAt(x, z);
        const yTerrain = Math.max(0, Math.min(H - 1, seatY + hGround));

        const rootFill = "minecraft:dark_prismarine";

        // If ground falls away below seat plane (shore seabed or slope)
        if (yTerrain < lowestOccupiedY) {
          for (let y = Math.max(0, yTerrain - 1); y < lowestOccupiedY; y++) {
            setVoxel(x, y, z, rootFill);
          }
        } else if (yTerrain > lowestOccupiedY) {
          // If ground rises above (hillside/ridge)
          for (let y = lowestOccupiedY; y <= Math.min(H - 1, yTerrain); y++) {
            if (!getVoxel(x, y, z)) {
              setVoxel(x, y, z, rootFill);
            }
          }
        }
      }
    }
  }

  // --- Final Emit ---
  for (let x = 0; x < W; x++) {
    for (let y = 0; y < H; y++) {
      for (let z = 0; z < D; z++) {
        const block = grid[idx(x, y, z)];
        if (block !== null) {
          api.set(x, y, z, block);
        }
      }
    }
  }

  return {
    name: "kraken_tentacle",
    seatY: seatY,
    anchors: {
      front: [Math.floor(W / 2), seatY, 0]
    }
  };
}
